-- Structured (v2) assessment templates + template-item provenance.
--
-- The consultant's point: a regulator reading a registration looks for
-- keywords, and free text hides them. v2 of the five system templates turns
-- every question a regulator reads into a structured one (choice / checklist /
-- scale / yes-no / date), each with an optional note, and carries the help
-- inside the question JSON. Reports render the labelled values.
--
-- Also adds the provenance quad to ai_systems / ai_vendors / ai_assessments so
-- "Remove all template items" can clear the rows an industry template created
-- silently, but only the ones nobody has edited.
--
-- ADDITIVE ONLY. New nullable/defaulted columns; new rows (v2 templates). No
-- table, column, type or row is dropped, renamed or retyped. Existing rows keep
-- their values; only the five v1 SYSTEM template rows receive a supersededAt so
-- new assessments pick v2 while existing assessments keep their v1 template.

-- 1. AIAssessmentTemplate: version + supersededAt (both nullable).
ALTER TABLE "ai_assessment_templates"
  ADD COLUMN "version" INTEGER,
  ADD COLUMN "supersededAt" TIMESTAMP(3);

-- 2. Provenance quad on the three template-created record types. Defaults to
--    USER_ENTERED so every pre-existing row is already correct and is never
--    removed automatically. The Provenance enum already exists.
ALTER TABLE "ai_systems"
  ADD COLUMN "provenance" "Provenance" NOT NULL DEFAULT 'USER_ENTERED',
  ADD COLUMN "sourceRef" TEXT,
  ADD COLUMN "confirmedBy" TEXT,
  ADD COLUMN "confirmedAt" TIMESTAMP(3);

ALTER TABLE "ai_vendors"
  ADD COLUMN "provenance" "Provenance" NOT NULL DEFAULT 'USER_ENTERED',
  ADD COLUMN "sourceRef" TEXT,
  ADD COLUMN "confirmedBy" TEXT,
  ADD COLUMN "confirmedAt" TIMESTAMP(3);

ALTER TABLE "ai_assessments"
  ADD COLUMN "provenance" "Provenance" NOT NULL DEFAULT 'USER_ENTERED',
  ADD COLUMN "sourceRef" TEXT,
  ADD COLUMN "confirmedBy" TEXT,
  ADD COLUMN "confirmedAt" TIMESTAMP(3);

-- 3. Seed the five v2 templates (idempotent: skip if the id already exists).
INSERT INTO "ai_assessment_templates"
  ("id", "organizationId", "name", "type", "description", "sections", "frameworkRef", "isSystem", "version", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-fria-template-v2', NULL, 'Fundamental Rights Impact Assessment', 'FRIA', 'EU AI Act Article 27 assessment of a high-risk system''s impact on fundamental rights, with structured answers a regulator can read.', '[{"id":"fria1","title":{"en":"AI system description","es":"Descripción del sistema de IA"},"questions":[{"id":"fria1_1","text":{"en":"Describe the AI system, including its name, version and intended purpose.","es":"Describe el sistema de IA, incluidos su nombre, versión y finalidad prevista."},"type":"text","required":true,"help":{"meaning":{"en":"Say what the system is and what it is for, so the rest of the assessment is anchored to a concrete thing.","es":"Di qué es el sistema y para qué sirve, de modo que el resto de la evaluación se ancle en algo concreto."},"example":{"en":"\"CV-Screen v2.1 ranks job applicants against a role''s requirements to produce a shortlist for recruiters.\"","es":"«CV-Screen v2.1 ordena a los candidatos según los requisitos del puesto para generar una preselección para los reclutadores.»"},"reference":{"en":"EU AI Act Art. 27(1)(a)","es":"Reglamento de IA de la UE, art. 27.1.a"}}},{"id":"fria1_2","text":{"en":"Describe the deployer''s processes in which the high-risk AI system will be used.","es":"Describe los procesos del responsable del despliegue en los que se usará el sistema de IA de alto riesgo."},"type":"text","required":true,"help":{"meaning":{"en":"Explain where the system sits in your own processes: what it feeds and what depends on its output.","es":"Explica dónde encaja el sistema en tus propios procesos: qué alimenta y qué depende de su resultado."},"example":{"en":"\"Recruiters receive the shortlist and decide who to interview; the system does not reject anyone on its own.\"","es":"«Los reclutadores reciben la preselección y deciden a quién entrevistar; el sistema no descarta a nadie por sí solo.»"},"reference":{"en":"EU AI Act Art. 27(1)(a)","es":"Reglamento de IA de la UE, art. 27.1.a"}}},{"id":"fria1_3","text":{"en":"What is the frequency of use?","es":"¿Con qué frecuencia se usa?"},"type":"single_choice","required":true,"options":[{"value":"continuous","label":{"en":"Continuous","es":"Continua"}},{"value":"periodic","label":{"en":"Periodic","es":"Periódica"}},{"value":"on_demand","label":{"en":"On demand","es":"Bajo demanda"}},{"value":"one_off","label":{"en":"One-off","es":"Puntual"}}],"allowNote":true,"help":{"meaning":{"en":"State for how long and how often the system will run, which bears on how much exposure it creates.","es":"Indica durante cuánto tiempo y con qué frecuencia funcionará el sistema, lo que influye en la exposición que genera."},"example":{"en":"\"In continuous use through each hiring campaign, roughly forty campaigns a year.\"","es":"«En uso continuo durante cada campaña de contratación, unas cuarenta campañas al año.»"},"reference":{"en":"EU AI Act Art. 27(1)(b)","es":"Reglamento de IA de la UE, art. 27.1.b"}}},{"id":"fria1_4","text":{"en":"What is the geographic and institutional scope of deployment?","es":"¿Cuál es el alcance geográfico e institucional del despliegue?"},"type":"text","required":true,"help":{"meaning":{"en":"Say where and in which parts of the organisation the system is deployed, so the scope of the assessment is clear.","es":"Di dónde y en qué partes de la organización se despliega el sistema, para que quede claro el alcance de la evaluación."},"example":{"en":"\"Used by the recruitment team across our offices in Spain and France.\"","es":"«Lo utiliza el equipo de selección en nuestras oficinas de España y Francia.»"},"reference":{"en":"EU AI Act Art. 27(1)(a)","es":"Reglamento de IA de la UE, art. 27.1.a"}}},{"id":"fria1_5","text":{"en":"Which EU AI Act Annex III high-risk area(s) does the system fall under?","es":"¿En qué ámbito(s) de alto riesgo del anexo III del Reglamento de IA de la UE se enmarca el sistema?"},"type":"multi_choice","required":true,"options":[{"value":"biometrics","label":{"en":"Biometrics","es":"Biometría"}},{"value":"critical_infrastructure","label":{"en":"Critical infrastructure","es":"Infraestructuras críticas"}},{"value":"education","label":{"en":"Education and vocational training","es":"Educación y formación profesional"}},{"value":"employment","label":{"en":"Employment and worker management","es":"Empleo y gestión de trabajadores"}},{"value":"essential_services","label":{"en":"Access to essential services","es":"Acceso a servicios esenciales"}},{"value":"law_enforcement","label":{"en":"Law enforcement","es":"Aplicación de la ley"}},{"value":"migration","label":{"en":"Migration, asylum and border control","es":"Migración, asilo y control fronterizo"}},{"value":"justice","label":{"en":"Administration of justice","es":"Administración de justicia"}},{"value":"none","label":{"en":"None of these","es":"Ninguna de estas"}}],"allowNote":true,"help":{"meaning":{"en":"Annex III lists the areas that make a system high-risk. Pick every area the system touches; this is the first keyword a regulator looks for.","es":"El anexo III enumera los ámbitos que hacen que un sistema sea de alto riesgo. Marca cada ámbito al que afecte el sistema; es la primera palabra clave que busca un regulador."},"example":{"en":"\"Employment and worker management\" for a CV-screening tool.","es":"«Empleo y gestión de trabajadores» para una herramienta de cribado de currículums."},"reference":{"en":"EU AI Act Annex III","es":"Reglamento de IA de la UE, anexo III"}}}]},{"id":"fria2","title":{"en":"Categories of affected persons","es":"Categorías de personas afectadas"},"questions":[{"id":"fria2_1","text":{"en":"Identify the categories of natural persons and groups likely to be affected.","es":"Identifica las categorías de personas físicas y grupos que probablemente se vean afectados."},"type":"text","required":true,"help":{"meaning":{"en":"Name the people and groups the system touches, not only its direct users but everyone its outputs reach.","es":"Nombra a las personas y los grupos a los que afecta el sistema, no solo a sus usuarios directos sino a todos a quienes llegan sus resultados."},"example":{"en":"\"Job applicants, the recruiters who use the shortlist, and the hiring managers who rely on it.\"","es":"«Los candidatos, los reclutadores que usan la preselección y los responsables de contratación que se apoyan en ella.»"},"reference":{"en":"EU AI Act Art. 27(1)(c)","es":"Reglamento de IA de la UE, art. 27.1.c"}}},{"id":"fria2_2","text":{"en":"Which affected groups are particularly vulnerable?","es":"¿Qué grupos afectados son especialmente vulnerables?"},"type":"multi_choice","required":true,"options":[{"value":"children","label":{"en":"Children","es":"Menores"}},{"value":"elderly","label":{"en":"Older people","es":"Personas mayores"}},{"value":"disability","label":{"en":"People with disabilities","es":"Personas con discapacidad"}},{"value":"ethnic_minorities","label":{"en":"Ethnic or racial minorities","es":"Minorías étnicas o raciales"}},{"value":"low_income","label":{"en":"People on low incomes","es":"Personas con bajos ingresos"}},{"value":"migrants","label":{"en":"Migrants or asylum seekers","es":"Migrantes o solicitantes de asilo"}},{"value":"none","label":{"en":"None identified","es":"Ninguno identificado"}}],"allowNote":true,"help":{"meaning":{"en":"Flag whether any affected group is more exposed to harm, which raises the care the system needs.","es":"Señala si algún grupo afectado está más expuesto al perjuicio, lo que eleva el cuidado que necesita el sistema."},"example":{"en":"\"Applicants with disabilities may be disadvantaged if the model reads career gaps as a negative signal.\"","es":"«Los candidatos con discapacidad pueden verse perjudicados si el modelo interpreta las interrupciones en la carrera como una señal negativa.»"},"reference":{"en":"EU AI Act Art. 27(1)(c)","es":"Reglamento de IA de la UE, art. 27.1.c"}}},{"id":"fria2_3","text":{"en":"Estimate the number of natural persons likely to be affected.","es":"Estima el número de personas físicas que probablemente se vean afectadas."},"type":"single_choice","required":true,"options":[{"value":"lt_100","label":{"en":"Fewer than 100","es":"Menos de 100"}},{"value":"100_1000","label":{"en":"100 to 1,000","es":"De 100 a 1.000"}},{"value":"1000_10000","label":{"en":"1,000 to 10,000","es":"De 1.000 a 10.000"}},{"value":"gt_10000","label":{"en":"More than 10,000","es":"Más de 10.000"}}],"allowNote":true,"help":{"meaning":{"en":"Give a rough number of people affected: the scale of harm matters as much as its likelihood.","es":"Da una cifra aproximada de personas afectadas: la escala del perjuicio importa tanto como su probabilidad."},"example":{"en":"\"About 8,000 applicants a year across all campaigns.\"","es":"«Unos 8.000 candidatos al año en todas las campañas.»"},"reference":{"en":"EU AI Act Art. 27(1)(c)","es":"Reglamento de IA de la UE, art. 27.1.c"}}},{"id":"fria2_4","text":{"en":"Were affected persons or their representatives consulted?","es":"¿Se consultó a las personas afectadas o a sus representantes?"},"type":"yes_no","required":true,"followUp":{"when":"yes","question":{"id":"fria2_4_detail","text":{"en":"Describe how they were consulted.","es":"Describe cómo se les consultó."},"type":"text","required":true}},"help":{"meaning":{"en":"Record whether affected people, or those who represent them, had any say in this assessment.","es":"Registra si las personas afectadas, o quienes las representan, tuvieron voz en esta evaluación."},"example":{"en":"\"The works council reviewed the tool and its concerns are recorded in the minutes of 12 March.\"","es":"«El comité de empresa revisó la herramienta y sus observaciones constan en el acta del 12 de marzo.»"},"reference":{"en":"EU AI Act Art. 27(1)(c)","es":"Reglamento de IA de la UE, art. 27.1.c"}}}]},{"id":"fria3","title":{"en":"Risks to fundamental rights","es":"Riesgos para los derechos fundamentales"},"questions":[{"id":"fria3_1","text":{"en":"Risk to the right to non-discrimination (Art. 21 EU Charter).","es":"Riesgo para el derecho a la no discriminación (art. 21 de la Carta de la UE)."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true,"help":{"meaning":{"en":"Identify how the system could treat people unfairly on a protected characteristic, whether or not that is intended.","es":"Identifica cómo el sistema podría tratar a las personas de forma injusta por una característica protegida, se pretenda o no."},"example":{"en":"\"Trained on past hires, the model may favour men for technical roles and so entrench a historical imbalance.\"","es":"«Entrenado con contrataciones pasadas, el modelo puede favorecer a los hombres en puestos técnicos y así perpetuar un desequilibrio histórico.»"},"reference":{"en":"Art. 21 EU Charter","es":"Art. 21 de la Carta de la UE"}}},{"id":"fria3_2","text":{"en":"Risk to privacy and data protection (Arts. 7-8 EU Charter).","es":"Riesgo para la privacidad y la protección de datos (arts. 7 y 8 de la Carta de la UE)."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true,"help":{"meaning":{"en":"Set out how the system could intrude on privacy or personal data, including what it can infer.","es":"Expón cómo el sistema podría vulnerar la privacidad o los datos personales, incluido lo que puede inferir."},"example":{"en":"\"The model could infer health or ethnicity from a CV and use it, even though those fields are never entered.\"","es":"«El modelo podría inferir salud u origen étnico a partir de un currículum y utilizarlo, aunque esos campos nunca se introduzcan.»"},"reference":{"en":"Arts. 7 and 8 EU Charter","es":"Arts. 7 y 8 de la Carta de la UE"}}},{"id":"fria3_3","text":{"en":"Risk to freedom of expression and information (Art. 11 EU Charter).","es":"Riesgo para la libertad de expresión e información (art. 11 de la Carta de la UE)."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true,"help":{"meaning":{"en":"Consider whether the system could chill or distort what people say or the information they receive.","es":"Considera si el sistema podría coartar o distorsionar lo que las personas dicen o la información que reciben."},"example":{"en":"\"Low risk here: the tool ranks CVs and does not moderate or shape any published content.\"","es":"«Riesgo bajo aquí: la herramienta ordena currículums y no modera ni condiciona ningún contenido publicado.»"},"reference":{"en":"Art. 11 EU Charter","es":"Art. 11 de la Carta de la UE"}}},{"id":"fria3_4","text":{"en":"Risk to human dignity (Art. 1 EU Charter).","es":"Riesgo para la dignidad humana (art. 1 de la Carta de la UE)."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true,"help":{"meaning":{"en":"Consider whether the system could treat people as mere data points rather than as people.","es":"Considera si el sistema podría tratar a las personas como meros datos y no como personas."},"example":{"en":"\"A purely automated rejection with no explanation could leave applicants feeling processed by a machine; a human review answers this.\"","es":"«Un rechazo puramente automático y sin explicación podría hacer que los candidatos se sintieran procesados por una máquina; una revisión humana lo corrige.»"},"reference":{"en":"Art. 1 EU Charter","es":"Art. 1 de la Carta de la UE"}}},{"id":"fria3_5","text":{"en":"Risk to an effective remedy and fair trial (Art. 47 EU Charter).","es":"Riesgo para la tutela judicial efectiva y a un juicio justo (art. 47 de la Carta de la UE)."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true,"help":{"meaning":{"en":"Consider whether affected people can understand, challenge and get redress for a decision the system shapes.","es":"Considera si las personas afectadas pueden comprender, impugnar y obtener reparación de una decisión que el sistema condiciona."},"example":{"en":"\"Rejected applicants can ask for a human review and reasons within fourteen days.\"","es":"«Los candidatos rechazados pueden solicitar una revisión humana y los motivos en un plazo de catorce días.»"},"reference":{"en":"Art. 47 EU Charter","es":"Art. 47 de la Carta de la UE"}}},{"id":"fria3_6","text":{"en":"Which other fundamental rights are at risk?","es":"¿Qué otros derechos fundamentales están en riesgo?"},"type":"multi_choice","required":false,"options":[{"value":"education","label":{"en":"Right to education (Art. 14)","es":"Derecho a la educación (art. 14)"}},{"value":"work","label":{"en":"Right to work (Art. 15)","es":"Derecho a trabajar (art. 15)"}},{"value":"child","label":{"en":"Rights of the child (Art. 24)","es":"Derechos del menor (art. 24)"}},{"value":"consumer","label":{"en":"Consumer protection (Art. 38)","es":"Protección de los consumidores (art. 38)"}},{"value":"none","label":{"en":"None","es":"Ninguno"}}],"allowNote":true,"help":{"meaning":{"en":"Note any other right the system could affect that the earlier questions did not cover.","es":"Anota cualquier otro derecho que el sistema pudiera afectar y que las preguntas anteriores no cubrieran."},"example":{"en":"\"Right to work (Art. 15): an over-strict filter could shut qualified people out of the labour market.\"","es":"«Derecho a trabajar (art. 15): un filtro demasiado estricto podría dejar fuera del mercado laboral a personas cualificadas.»"},"reference":{"en":"EU Charter of Fundamental Rights","es":"Carta de los Derechos Fundamentales de la UE"}}}]},{"id":"fria4","title":{"en":"Human oversight and safeguards","es":"Supervisión humana y salvaguardas"},"questions":[{"id":"fria4_1","text":{"en":"Which human oversight measures are in place?","es":"¿Qué medidas de supervisión humana existen?"},"type":"multi_choice","required":true,"options":[{"value":"human_in_the_loop","label":{"en":"Human in the loop (a person acts on each output)","es":"Humano en el bucle (una persona actúa sobre cada resultado)"}},{"value":"human_on_the_loop","label":{"en":"Human on the loop (a person monitors and can step in)","es":"Humano sobre el bucle (una persona supervisa y puede intervenir)"}},{"value":"human_in_command","label":{"en":"Human in command (a person sets and can suspend the system)","es":"Humano al mando (una persona fija y puede suspender el sistema)"}},{"value":"override","label":{"en":"Ability to override an output","es":"Posibilidad de anular un resultado"}},{"value":"stop","label":{"en":"Ability to halt the system","es":"Posibilidad de detener el sistema"}},{"value":"training","label":{"en":"Trained overseers","es":"Supervisores formados"}}],"allowNote":true,"help":{"meaning":{"en":"Describe who watches over the system in use, how competent they are, and how they can step in.","es":"Describe quién supervisa el sistema en uso, qué competencia tiene y cómo puede intervenir."},"example":{"en":"\"A trained recruiter reviews every shortlist and can add or remove candidates before anyone is contacted.\"","es":"«Un reclutador formado revisa cada preselección y puede añadir o quitar candidatos antes de contactar con nadie.»"},"reference":{"en":"EU AI Act Arts. 14 and 27(1)(e)","es":"Reglamento de IA de la UE, arts. 14 y 27.1.e"}}},{"id":"fria4_2","text":{"en":"Which technical safeguards protect fundamental rights?","es":"¿Qué salvaguardas técnicas protegen los derechos fundamentales?"},"type":"multi_choice","required":true,"options":[{"value":"bias_detection","label":{"en":"Bias detection","es":"Detección de sesgos"}},{"value":"fairness_constraints","label":{"en":"Fairness constraints","es":"Restricciones de equidad"}},{"value":"explainability","label":{"en":"Explainability of outputs","es":"Explicabilidad de los resultados"}},{"value":"accuracy_monitoring","label":{"en":"Accuracy monitoring","es":"Vigilancia de la exactitud"}},{"value":"logging","label":{"en":"Logging and traceability","es":"Registro y trazabilidad"}},{"value":"access_control","label":{"en":"Access control","es":"Control de acceso"}}],"allowNote":true,"help":{"meaning":{"en":"List the built-in technical measures that protect people''s rights, not just the system''s accuracy.","es":"Enumera las medidas técnicas integradas que protegen los derechos de las personas, no solo la exactitud del sistema."},"example":{"en":"\"Sensitive attributes are excluded, outputs are tested for disparate impact each quarter, and each score carries its main reasons.\"","es":"«Se excluyen los atributos sensibles, los resultados se prueban trimestralmente en busca de impacto desigual y cada puntuación indica sus motivos principales.»"},"reference":{"en":"EU AI Act Arts. 9, 10 and 15","es":"Reglamento de IA de la UE, arts. 9, 10 y 15"}}},{"id":"fria4_3","text":{"en":"Which organisational measures mitigate the identified risks?","es":"¿Qué medidas organizativas mitigan los riesgos identificados?"},"type":"multi_choice","required":true,"options":[{"value":"training","label":{"en":"Staff training","es":"Formación del personal"}},{"value":"oversight_committee","label":{"en":"Oversight committee","es":"Comité de supervisión"}},{"value":"audits","label":{"en":"Regular audits","es":"Auditorías periódicas"}},{"value":"escalation","label":{"en":"Escalation procedure","es":"Procedimiento de escalado"}},{"value":"incident_response","label":{"en":"Incident response plan","es":"Plan de respuesta a incidentes"}}],"allowNote":true,"help":{"meaning":{"en":"List the organisational measures, the things people and procedures do, that reduce the risks you found.","es":"Enumera las medidas organizativas, lo que hacen las personas y los procedimientos, que reducen los riesgos que has hallado."},"example":{"en":"\"Recruiters are trained on the tool''s limits, an oversight group reviews outcomes quarterly, and concerns escalate to the AI officer.\"","es":"«Los reclutadores reciben formación sobre los límites de la herramienta, un grupo de supervisión revisa los resultados cada trimestre y las incidencias se elevan al responsable de IA.»"},"reference":{"en":"EU AI Act Art. 27(1)(e)","es":"Reglamento de IA de la UE, art. 27.1.e"}}},{"id":"fria4_4","text":{"en":"Can affected persons contest decisions or seek redress?","es":"¿Pueden las personas afectadas impugnar las decisiones o solicitar reparación?"},"type":"yes_no","required":true,"followUp":{"when":"yes","question":{"id":"fria4_4_detail","text":{"en":"Describe the complaint, appeal or human-review mechanism.","es":"Describe el mecanismo de reclamación, recurso o revisión humana."},"type":"text","required":true}},"help":{"meaning":{"en":"Say how an affected person can contest a decision the system shaped and get it looked at again.","es":"Di cómo una persona afectada puede impugnar una decisión condicionada por el sistema y conseguir que se revise."},"example":{"en":"\"A rejected applicant can request a human review through a named contact and receives a reasoned reply.\"","es":"«Un candidato rechazado puede solicitar una revisión humana a través de un contacto designado y recibe una respuesta motivada.»"},"reference":{"en":"EU AI Act Art. 27(1)(f); Art. 47 EU Charter","es":"Reglamento de IA de la UE, art. 27.1.f; art. 47 de la Carta de la UE"}}}]},{"id":"fria5","title":{"en":"Assessment outcome and notification","es":"Resultado de la evaluación y notificación"},"questions":[{"id":"fria5_1","text":{"en":"What is the overall assessment of impact on fundamental rights?","es":"¿Cuál es la valoración general del impacto sobre los derechos fundamentales?"},"type":"single_choice","required":true,"options":[{"value":"acceptable","label":{"en":"Acceptable","es":"Aceptable"}},{"value":"acceptable_conditions","label":{"en":"Acceptable with conditions","es":"Aceptable con condiciones"}},{"value":"not_acceptable","label":{"en":"Not acceptable","es":"No aceptable"}}],"allowNote":true,"help":{"meaning":{"en":"Give your overall reading: taking the safeguards into account, are the risks to rights acceptable?","es":"Da tu valoración general: teniendo en cuenta las salvaguardas, ¿son aceptables los riesgos para los derechos?"},"example":{"en":"\"With human review and quarterly bias testing in place, the residual risks are acceptable and monitored.\"","es":"«Con la revisión humana y las pruebas de sesgo trimestrales, los riesgos residuales son aceptables y se vigilan.»"},"reference":{"en":"EU AI Act Art. 27(1)(d)","es":"Reglamento de IA de la UE, art. 27.1.d"}}},{"id":"fria5_2","text":{"en":"What residual risks remain after mitigation measures?","es":"¿Qué riesgos residuales quedan tras las medidas de mitigación?"},"type":"text","required":true,"help":{"meaning":{"en":"State what risk is left after the safeguards, because no set of measures removes all of it.","es":"Indica qué riesgo queda tras las salvaguardas, porque ningún conjunto de medidas lo elimina por completo."},"example":{"en":"\"A small risk of indirect bias remains where career gaps correlate with protected groups; it is watched in the quarterly test.\"","es":"«Queda un pequeño riesgo de sesgo indirecto cuando las interrupciones de carrera se correlacionan con grupos protegidos; se vigila en la prueba trimestral.»"},"reference":{"en":"EU AI Act Art. 9(2)","es":"Reglamento de IA de la UE, art. 9.2"}}},{"id":"fria5_3","text":{"en":"What additional measures are recommended?","es":"¿Qué medidas adicionales se recomiendan?"},"type":"text","required":false,"help":{"meaning":{"en":"Note any further measures worth taking to bring the residual risk down.","es":"Anota cualquier medida adicional que convenga adoptar para reducir el riesgo residual."},"example":{"en":"\"Add an annual external audit of the model''s outcomes and widen the test to intersectional groups.\"","es":"«Añadir una auditoría externa anual de los resultados del modelo y ampliar la prueba a grupos interseccionales.»"},"reference":{"en":"EU AI Act Art. 9","es":"Reglamento de IA de la UE, art. 9"}}},{"id":"fria5_4","text":{"en":"Has the market surveillance authority been notified (Art. 27(3))?","es":"¿Se ha notificado a la autoridad de vigilancia del mercado (art. 27.3)?"},"type":"yes_no","required":true,"followUp":{"when":"yes","question":{"id":"fria5_4_date","text":{"en":"Date of notification.","es":"Fecha de la notificación."},"type":"date","required":true}},"help":{"meaning":{"en":"Record whether, and how, you told the market surveillance authority the results, where that duty applies.","es":"Registra si comunicaste los resultados a la autoridad de vigilancia del mercado, y cómo, cuando esa obligación aplica."},"example":{"en":"\"Notified through the national authority''s template on 3 April; reference number recorded in the file.\"","es":"«Notificado mediante el modelo de la autoridad nacional el 3 de abril; el número de referencia consta en el expediente.»"},"reference":{"en":"EU AI Act Art. 27(3)","es":"Reglamento de IA de la UE, art. 27.3"}}}]}]'::jsonb, 'EU AI Act Art. 27', true, 2, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "ai_assessment_templates"
  ("id", "organizationId", "name", "type", "description", "sections", "frameworkRef", "isSystem", "version", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-ai-risk-template-v2', NULL, 'AI Risk Assessment', 'AI_RISK', 'Structured AI risk assessment covering technical, ethical and operational risks and their mitigations, aligned with NIST AI RMF and ISO 42001.', '[{"id":"air1","title":{"en":"System overview and context","es":"Descripción y contexto del sistema"},"questions":[{"id":"air1_1","text":{"en":"Describe the AI system, its purpose and key capabilities.","es":"Describe el sistema de IA, su finalidad y sus capacidades principales."},"type":"text","required":true},{"id":"air1_2","text":{"en":"What is the risk classification of this system?","es":"¿Cuál es la clasificación de riesgo de este sistema?"},"type":"single_choice","required":true,"options":[{"value":"minimal","label":{"en":"Minimal","es":"Mínimo"}},{"value":"limited","label":{"en":"Limited","es":"Limitado"}},{"value":"high","label":{"en":"High","es":"Alto"}},{"value":"unacceptable","label":{"en":"Unacceptable","es":"Inaceptable"}}],"allowNote":true},{"id":"air1_3","text":{"en":"Who are the intended users and affected stakeholders?","es":"¿Quiénes son los usuarios previstos y las partes afectadas?"},"type":"text","required":true}]},{"id":"air2","title":{"en":"Technical risks","es":"Riesgos técnicos"},"questions":[{"id":"air2_1","text":{"en":"Risk from model accuracy limitations or errors.","es":"Riesgo por limitaciones o errores en la exactitud del modelo."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true},{"id":"air2_2","text":{"en":"Risk from model drift or performance degradation over time.","es":"Riesgo por deriva del modelo o degradación del rendimiento con el tiempo."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true},{"id":"air2_3","text":{"en":"Which cybersecurity risks apply?","es":"¿Qué riesgos de ciberseguridad aplican?"},"type":"multi_choice","required":true,"options":[{"value":"adversarial","label":{"en":"Adversarial attacks","es":"Ataques adversarios"}},{"value":"prompt_injection","label":{"en":"Prompt injection","es":"Inyección de instrucciones"}},{"value":"data_poisoning","label":{"en":"Data poisoning","es":"Envenenamiento de datos"}},{"value":"model_theft","label":{"en":"Model theft","es":"Robo del modelo"}},{"value":"inference","label":{"en":"Inference attacks","es":"Ataques de inferencia"}},{"value":"none","label":{"en":"None identified","es":"Ninguno identificado"}}],"allowNote":true}]},{"id":"air3","title":{"en":"Ethical and fairness risks","es":"Riesgos éticos y de equidad"},"questions":[{"id":"air3_1","text":{"en":"Which bias or discrimination risks have been identified?","es":"¿Qué riesgos de sesgo o discriminación se han identificado?"},"type":"multi_choice","required":true,"options":[{"value":"historical","label":{"en":"Historical bias","es":"Sesgo histórico"}},{"value":"representation","label":{"en":"Representation bias","es":"Sesgo de representación"}},{"value":"measurement","label":{"en":"Measurement bias","es":"Sesgo de medición"}},{"value":"aggregation","label":{"en":"Aggregation bias","es":"Sesgo de agregación"}},{"value":"evaluation","label":{"en":"Evaluation bias","es":"Sesgo de evaluación"}},{"value":"none","label":{"en":"None identified","es":"Ninguno identificado"}}],"allowNote":true,"help":{"meaning":{"en":"Name the kinds of bias present, not just \"there is bias\". The taxonomy tells a reviewer where to look.","es":"Nombra los tipos de sesgo presentes, no solo «hay sesgo». La taxonomía indica al revisor dónde mirar."},"example":{"en":"\"Historical bias: the training data reflects past hiring that favoured men.\"","es":"«Sesgo histórico: los datos de entrenamiento reflejan contrataciones pasadas que favorecían a los hombres.»"}}},{"id":"air3_2","text":{"en":"How explainable are the system''s decisions?","es":"¿Cómo de explicables son las decisiones del sistema?"},"type":"single_choice","required":true,"options":[{"value":"fully","label":{"en":"Fully explainable","es":"Totalmente explicables"}},{"value":"partially","label":{"en":"Partially explainable","es":"Parcialmente explicables"}},{"value":"limited","label":{"en":"Limited explainability","es":"Explicabilidad limitada"}},{"value":"black_box","label":{"en":"Black box","es":"Caja negra"}}],"allowNote":true},{"id":"air3_3","text":{"en":"Risk to individual autonomy or human agency.","es":"Riesgo para la autonomía individual o la agencia humana."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true}]},{"id":"air4","title":{"en":"Operational risks","es":"Riesgos operativos"},"questions":[{"id":"air4_1","text":{"en":"What happens if the system becomes unavailable or fails?","es":"¿Qué ocurre si el sistema deja de estar disponible o falla?"},"type":"text","required":true},{"id":"air4_2","text":{"en":"Data quality and data governance risk.","es":"Riesgo de calidad y gobernanza de los datos."},"type":"scale","required":true,"scale":{"min":1,"max":5,"minLabel":{"en":"No real risk","es":"Sin riesgo real"},"maxLabel":{"en":"Severe risk","es":"Riesgo grave"}},"allowNote":true},{"id":"air4_3","text":{"en":"Which third-party dependency risks apply?","es":"¿Qué riesgos de dependencia de terceros aplican?"},"type":"multi_choice","required":false,"options":[{"value":"vendor_lock_in","label":{"en":"Vendor lock-in","es":"Dependencia de un proveedor"}},{"value":"api_changes","label":{"en":"API changes","es":"Cambios en la API"}},{"value":"model_deprecation","label":{"en":"Model deprecation","es":"Retirada del modelo"}},{"value":"supply_chain","label":{"en":"Supply chain risk","es":"Riesgo de la cadena de suministro"}},{"value":"none","label":{"en":"None identified","es":"Ninguno identificado"}}],"allowNote":true}]},{"id":"air5","title":{"en":"Mitigation measures","es":"Medidas de mitigación"},"questions":[{"id":"air5_1","text":{"en":"Which technical safeguards are in place or planned?","es":"¿Qué salvaguardas técnicas existen o están previstas?"},"type":"multi_choice","required":true,"options":[{"value":"monitoring","label":{"en":"Monitoring and alerting","es":"Vigilancia y alertas"}},{"value":"testing","label":{"en":"Testing pipelines","es":"Cadenas de pruebas"}},{"value":"bias_detection","label":{"en":"Bias detection","es":"Detección de sesgos"}},{"value":"adversarial_testing","label":{"en":"Adversarial testing","es":"Pruebas adversarias"}},{"value":"access_control","label":{"en":"Access control","es":"Control de acceso"}}],"allowNote":true},{"id":"air5_2","text":{"en":"Which organisational safeguards are in place or planned?","es":"¿Qué salvaguardas organizativas existen o están previstas?"},"type":"multi_choice","required":true,"options":[{"value":"training","label":{"en":"Training","es":"Formación"}},{"value":"oversight_committee","label":{"en":"Oversight committee","es":"Comité de supervisión"}},{"value":"incident_response","label":{"en":"Incident response plan","es":"Plan de respuesta a incidentes"}},{"value":"audits","label":{"en":"Regular audits","es":"Auditorías periódicas"}}],"allowNote":true},{"id":"air5_3","text":{"en":"What human oversight arrangement is in place?","es":"¿Qué mecanismo de supervisión humana existe?"},"type":"single_choice","required":true,"options":[{"value":"human_in_the_loop","label":{"en":"Human in the loop","es":"Humano en el bucle"}},{"value":"human_on_the_loop","label":{"en":"Human on the loop","es":"Humano sobre el bucle"}},{"value":"human_in_command","label":{"en":"Human in command","es":"Humano al mando"}},{"value":"none","label":{"en":"None","es":"Ninguno"}}],"allowNote":true}]},{"id":"air6","title":{"en":"Risk summary and recommendations","es":"Resumen de riesgos y recomendaciones"},"questions":[{"id":"air6_1","text":{"en":"What is the overall residual risk after mitigation?","es":"¿Cuál es el riesgo residual global tras la mitigación?"},"type":"single_choice","required":true,"options":[{"value":"low","label":{"en":"Low","es":"Bajo"}},{"value":"medium","label":{"en":"Medium","es":"Medio"}},{"value":"high","label":{"en":"High","es":"Alto"}},{"value":"critical","label":{"en":"Critical","es":"Crítico"}}],"allowNote":true},{"id":"air6_2","text":{"en":"Is the residual risk acceptable?","es":"¿Es aceptable el riesgo residual?"},"type":"yes_no","required":true,"followUp":{"when":"no","question":{"id":"air6_2_detail","text":{"en":"What must change for it to be acceptable?","es":"¿Qué debe cambiar para que sea aceptable?"},"type":"text","required":true}}},{"id":"air6_3","text":{"en":"What additional actions or follow-up reviews are recommended?","es":"¿Qué acciones adicionales o revisiones de seguimiento se recomiendan?"},"type":"text","required":false}]}]'::jsonb, 'NIST AI RMF / ISO 42001', true, 2, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "ai_assessment_templates"
  ("id", "organizationId", "name", "type", "description", "sections", "frameworkRef", "isSystem", "version", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-custom-template-v2', NULL, 'Custom Assessment', 'CUSTOM', 'A flexible assessment for custom AI governance reviews, with structured risk answers and room for a written rationale.', '[{"id":"custom1","title":{"en":"Overview","es":"Descripción"},"questions":[{"id":"custom1_1","text":{"en":"What is the purpose of this assessment?","es":"¿Cuál es el propósito de esta evaluación?"},"type":"text","required":true},{"id":"custom1_2","text":{"en":"What is the scope of this assessment?","es":"¿Cuál es el alcance de esta evaluación?"},"type":"text","required":true}]},{"id":"custom2","title":{"en":"Risk evaluation","es":"Evaluación del riesgo"},"questions":[{"id":"custom2_1","text":{"en":"What are the key risks identified?","es":"¿Cuáles son los principales riesgos identificados?"},"type":"text","required":true},{"id":"custom2_2","text":{"en":"What is the overall risk level?","es":"¿Cuál es el nivel de riesgo global?"},"type":"single_choice","required":true,"options":[{"value":"low","label":{"en":"Low","es":"Bajo"}},{"value":"medium","label":{"en":"Medium","es":"Medio"}},{"value":"high","label":{"en":"High","es":"Alto"}},{"value":"critical","label":{"en":"Critical","es":"Crítico"}}],"allowNote":true}]},{"id":"custom3","title":{"en":"Mitigations and recommendations","es":"Mitigaciones y recomendaciones"},"questions":[{"id":"custom3_1","text":{"en":"What mitigations are in place or recommended?","es":"¿Qué mitigaciones existen o se recomiendan?"},"type":"text","required":true},{"id":"custom3_2","text":{"en":"Is the residual risk acceptable?","es":"¿Es aceptable el riesgo residual?"},"type":"single_choice","required":true,"options":[{"value":"fully","label":{"en":"Yes, fully acceptable","es":"Sí, plenamente aceptable"}},{"value":"conditions","label":{"en":"Acceptable with conditions","es":"Aceptable con condiciones"}},{"value":"review","label":{"en":"Needs further review","es":"Necesita más revisión"}},{"value":"not_acceptable","label":{"en":"Not acceptable","es":"No aceptable"}}],"allowNote":true}]}]'::jsonb, NULL, true, 2, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "ai_assessment_templates"
  ("id", "organizationId", "name", "type", "description", "sections", "frameworkRef", "isSystem", "version", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-conformity-template-v2', NULL, 'Conformity Assessment', 'CONFORMITY', 'EU AI Act Article 43 conformity assessment for high-risk systems: quality management, technical documentation, risk management, transparency and the declaration, with structured answers.', '[{"id":"conf1","title":{"en":"System identification","es":"Identificación del sistema"},"questions":[{"id":"conf1_1","text":{"en":"What is the name, version and unique identifier of the system?","es":"¿Cuál es el nombre, la versión y el identificador único del sistema?"},"type":"text","required":true},{"id":"conf1_2","text":{"en":"Who is the provider and what are their contact details?","es":"¿Quién es el proveedor y cuáles son sus datos de contacto?"},"type":"text","required":true},{"id":"conf1_3","text":{"en":"What is the intended purpose of the system?","es":"¿Cuál es la finalidad prevista del sistema?"},"type":"text","required":true},{"id":"conf1_4","text":{"en":"What is the risk classification under the EU AI Act?","es":"¿Cuál es la clasificación de riesgo conforme al Reglamento de IA de la UE?"},"type":"single_choice","required":true,"options":[{"value":"annex_iii","label":{"en":"High-risk (Annex III)","es":"Alto riesgo (anexo III)"}},{"value":"union_harmonisation","label":{"en":"High-risk (Union harmonisation legislation)","es":"Alto riesgo (legislación de armonización de la Unión)"}},{"value":"limited","label":{"en":"Limited risk","es":"Riesgo limitado"}},{"value":"minimal","label":{"en":"Minimal risk","es":"Riesgo mínimo"}}],"allowNote":true},{"id":"conf1_5","text":{"en":"Which Annex III category does the system fall under?","es":"¿En qué categoría del anexo III se enmarca el sistema?"},"type":"single_choice","required":false,"options":[{"value":"biometrics","label":{"en":"Biometrics","es":"Biometría"}},{"value":"critical_infrastructure","label":{"en":"Critical infrastructure","es":"Infraestructuras críticas"}},{"value":"education","label":{"en":"Education and vocational training","es":"Educación y formación profesional"}},{"value":"employment","label":{"en":"Employment and worker management","es":"Empleo y gestión de trabajadores"}},{"value":"essential_services","label":{"en":"Access to essential services","es":"Acceso a servicios esenciales"}},{"value":"law_enforcement","label":{"en":"Law enforcement","es":"Aplicación de la ley"}},{"value":"migration","label":{"en":"Migration, asylum and border control","es":"Migración, asilo y control fronterizo"}},{"value":"justice","label":{"en":"Administration of justice","es":"Administración de justicia"}},{"value":"none","label":{"en":"None of these","es":"Ninguna de estas"}}],"allowNote":true}]},{"id":"conf2","title":{"en":"Quality management system","es":"Sistema de gestión de la calidad"},"questions":[{"id":"conf2_1","text":{"en":"Is there a documented Quality Management System covering the system?","es":"¿Existe un sistema de gestión de la calidad documentado que cubra el sistema?"},"type":"single_choice","required":true,"options":[{"value":"full","label":{"en":"Yes, fully documented","es":"Sí, plenamente documentado"}},{"value":"partial","label":{"en":"Partially documented","es":"Parcialmente documentado"}},{"value":"in_progress","label":{"en":"Under development","es":"En desarrollo"}},{"value":"none","label":{"en":"No","es":"No"}}],"allowNote":true},{"id":"conf2_2","text":{"en":"Describe the design and development procedures within the QMS.","es":"Describe los procedimientos de diseño y desarrollo dentro del SGC."},"type":"text","required":true},{"id":"conf2_3","text":{"en":"Describe the testing and validation methodology.","es":"Describe la metodología de pruebas y validación."},"type":"text","required":true},{"id":"conf2_4","text":{"en":"Describe the post-market monitoring plan.","es":"Describe el plan de seguimiento poscomercialización."},"type":"text","required":true}]},{"id":"conf3","title":{"en":"Technical documentation","es":"Documentación técnica"},"questions":[{"id":"conf3_1","text":{"en":"Describe the system architecture and key components.","es":"Describe la arquitectura del sistema y sus componentes principales."},"type":"text","required":true},{"id":"conf3_2","text":{"en":"Describe the training data: source, scope and characteristics.","es":"Describe los datos de entrenamiento: origen, alcance y características."},"type":"text","required":true},{"id":"conf3_3","text":{"en":"Which data governance measures are in place (Art. 10)?","es":"¿Qué medidas de gobernanza de datos existen (art. 10)?"},"type":"multi_choice","required":true,"options":[{"value":"quality_controls","label":{"en":"Data quality controls","es":"Controles de calidad de los datos"}},{"value":"bias_examination","label":{"en":"Bias examination","es":"Examen de sesgos"}},{"value":"relevance","label":{"en":"Relevance assessment","es":"Evaluación de la pertinencia"}},{"value":"gdpr","label":{"en":"GDPR compliance measures","es":"Medidas de cumplimiento del RGPD"}},{"value":"none","label":{"en":"None yet","es":"Todavía ninguna"}}],"allowNote":true},{"id":"conf3_4","text":{"en":"What are the documented performance metrics and benchmarks?","es":"¿Cuáles son las métricas de rendimiento y los valores de referencia documentados?"},"type":"text","required":true}]},{"id":"conf4","title":{"en":"Risk management","es":"Gestión de riesgos"},"questions":[{"id":"conf4_1","text":{"en":"Describe the risk identification and analysis methodology (Art. 9).","es":"Describe la metodología de identificación y análisis de riesgos (art. 9)."},"type":"text","required":true},{"id":"conf4_2","text":{"en":"List the known and foreseeable risks and their mitigations.","es":"Enumera los riesgos conocidos y previsibles y sus mitigaciones."},"type":"text","required":true},{"id":"conf4_3","text":{"en":"Is the residual risk acceptable after all mitigations?","es":"¿Es aceptable el riesgo residual tras todas las mitigaciones?"},"type":"single_choice","required":true,"options":[{"value":"fully","label":{"en":"Yes, fully acceptable","es":"Sí, plenamente aceptable"}},{"value":"conditions","label":{"en":"Acceptable with conditions","es":"Aceptable con condiciones"}},{"value":"further","label":{"en":"Requires further mitigation","es":"Requiere más mitigación"}},{"value":"not_acceptable","label":{"en":"Not acceptable","es":"No aceptable"}}],"allowNote":true},{"id":"conf4_4","text":{"en":"Has the system been tested against relevant harmonised standards?","es":"¿Se ha probado el sistema frente a las normas armonizadas pertinentes?"},"type":"single_choice","required":true,"options":[{"value":"full","label":{"en":"Yes, fully tested","es":"Sí, probado por completo"}},{"value":"partial","label":{"en":"Partially tested","es":"Probado parcialmente"}},{"value":"planned","label":{"en":"Planned","es":"Previsto"}},{"value":"none","label":{"en":"No applicable standards identified","es":"No se han identificado normas aplicables"}}],"allowNote":true}]},{"id":"conf5","title":{"en":"Transparency and human oversight","es":"Transparencia y supervisión humana"},"questions":[{"id":"conf5_1","text":{"en":"Describe the instructions for use provided to deployers (Art. 13).","es":"Describe las instrucciones de uso facilitadas a los responsables del despliegue (art. 13)."},"type":"text","required":true},{"id":"conf5_2","text":{"en":"Are users informed they are interacting with an AI system?","es":"¿Se informa a los usuarios de que interactúan con un sistema de IA?"},"type":"yes_no","required":true,"followUp":{"when":"yes","question":{"id":"conf5_2_detail","text":{"en":"How are they informed, and how are outputs made interpretable?","es":"¿Cómo se les informa y cómo se hacen interpretables los resultados?"},"type":"text","required":true}}},{"id":"conf5_3","text":{"en":"Which human oversight mechanism is implemented?","es":"¿Qué mecanismo de supervisión humana se ha implantado?"},"type":"single_choice","required":true,"options":[{"value":"human_in_the_loop","label":{"en":"Human in the loop","es":"Humano en el bucle"}},{"value":"human_on_the_loop","label":{"en":"Human on the loop","es":"Humano sobre el bucle"}},{"value":"human_in_command","label":{"en":"Human in command","es":"Humano al mando"}},{"value":"multiple","label":{"en":"Multiple mechanisms","es":"Varios mecanismos"}},{"value":"none","label":{"en":"None","es":"Ninguno"}}],"allowNote":true},{"id":"conf5_4","text":{"en":"Describe the logging capabilities of the system (Art. 12).","es":"Describe las capacidades de registro del sistema (art. 12)."},"type":"text","required":true}]},{"id":"conf6","title":{"en":"Conformity declaration","es":"Declaración de conformidad"},"questions":[{"id":"conf6_1","text":{"en":"What is the overall conformity conclusion?","es":"¿Cuál es la conclusión general de conformidad?"},"type":"single_choice","required":true,"options":[{"value":"conforms","label":{"en":"Conforms to all applicable requirements","es":"Conforme con todos los requisitos aplicables"}},{"value":"minor","label":{"en":"Conforms with minor observations","es":"Conforme con observaciones menores"}},{"value":"not_conform","label":{"en":"Does not conform — corrective actions required","es":"No conforme: se requieren acciones correctivas"}}],"allowNote":true},{"id":"conf6_2","text":{"en":"Which conformity assessment pathway is being followed?","es":"¿Qué vía de evaluación de la conformidad se sigue?"},"type":"single_choice","required":true,"options":[{"value":"annex_vi","label":{"en":"Annex VI — internal control (self-assessment)","es":"Anexo VI: control interno (autoevaluación)"}},{"value":"annex_vii","label":{"en":"Annex VII — assessment by notified body","es":"Anexo VII: evaluación por organismo notificado"}}],"allowNote":true,"help":{"meaning":{"en":"Annex VI is self-assessment; Annex VII involves a notified body. Which one applies depends on the system and the harmonised standards used.","es":"El anexo VI es autoevaluación; el anexo VII implica a un organismo notificado. Cuál aplica depende del sistema y de las normas armonizadas utilizadas."},"example":{"en":"\"Annex VI — internal control, since harmonised standards are applied in full.\"","es":"«Anexo VI: control interno, ya que se aplican íntegramente las normas armonizadas.»"},"reference":{"en":"EU AI Act Art. 43","es":"Reglamento de IA de la UE, art. 43"}}},{"id":"conf6_3","text":{"en":"If Annex VII applies, give the notified body details.","es":"Si aplica el anexo VII, indica los datos del organismo notificado."},"type":"text","required":false},{"id":"conf6_4","text":{"en":"Is the EU Declaration of Conformity drafted and CE marking ready?","es":"¿Está redactada la declaración UE de conformidad y lista el marcado CE?"},"type":"single_choice","required":true,"options":[{"value":"ready","label":{"en":"Yes, declaration drafted and CE marking ready","es":"Sí, declaración redactada y marcado CE listo"}},{"value":"in_progress","label":{"en":"Declaration in progress","es":"Declaración en curso"}},{"value":"not_started","label":{"en":"Not yet started","es":"Todavía no iniciada"}}],"allowNote":true}]}]'::jsonb, 'EU AI Act Art. 43, Annex VI, Annex VII', true, 2, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

INSERT INTO "ai_assessment_templates"
  ("id", "organizationId", "name", "type", "description", "sections", "frameworkRef", "isSystem", "version", "supersededAt", "createdAt", "updatedAt")
VALUES
  ('system-bias-fairness-template-v2', NULL, 'Bias & Fairness Assessment', 'BIAS_FAIRNESS', 'Structured bias and fairness assessment covering data composition, fairness metrics, disaggregated testing and mitigation, aligned with EU AI Act Article 10 and NIST AI RMF.', '[{"id":"bf1","title":{"en":"Assessment scope","es":"Alcance de la evaluación"},"questions":[{"id":"bf1_1","text":{"en":"What system is being assessed, and which version?","es":"¿Qué sistema se evalúa y en qué versión?"},"type":"text","required":true},{"id":"bf1_2","text":{"en":"What is the decision domain of this system?","es":"¿Cuál es el ámbito de decisión de este sistema?"},"type":"single_choice","required":true,"options":[{"value":"hiring","label":{"en":"Hiring and recruitment","es":"Contratación y selección"}},{"value":"credit","label":{"en":"Credit and lending","es":"Crédito y préstamos"}},{"value":"healthcare","label":{"en":"Healthcare","es":"Sanidad"}},{"value":"criminal_justice","label":{"en":"Criminal justice","es":"Justicia penal"}},{"value":"education","label":{"en":"Education","es":"Educación"}},{"value":"insurance","label":{"en":"Insurance","es":"Seguros"}},{"value":"social_services","label":{"en":"Social services","es":"Servicios sociales"}},{"value":"content_moderation","label":{"en":"Content moderation","es":"Moderación de contenidos"}},{"value":"other","label":{"en":"Other","es":"Otro"}}],"allowNote":true},{"id":"bf1_3","text":{"en":"Describe the affected populations and stakeholders.","es":"Describe las poblaciones afectadas y las partes interesadas."},"type":"text","required":true},{"id":"bf1_4","text":{"en":"Which protected characteristics are considered?","es":"¿Qué características protegidas se consideran?"},"type":"multi_choice","required":true,"options":[{"value":"race","label":{"en":"Race or ethnicity","es":"Raza u origen étnico"}},{"value":"gender","label":{"en":"Gender","es":"Género"}},{"value":"age","label":{"en":"Age","es":"Edad"}},{"value":"disability","label":{"en":"Disability","es":"Discapacidad"}},{"value":"religion","label":{"en":"Religion","es":"Religión"}},{"value":"sexual_orientation","label":{"en":"Sexual orientation","es":"Orientación sexual"}},{"value":"nationality","label":{"en":"Nationality","es":"Nacionalidad"}},{"value":"socioeconomic","label":{"en":"Socioeconomic status","es":"Situación socioeconómica"}}],"allowNote":true}]},{"id":"bf2","title":{"en":"Data analysis","es":"Análisis de los datos"},"questions":[{"id":"bf2_1","text":{"en":"Describe the composition of the training data.","es":"Describe la composición de los datos de entrenamiento."},"type":"text","required":true},{"id":"bf2_2","text":{"en":"What is the demographic representation in the training data?","es":"¿Cuál es la representación demográfica en los datos de entrenamiento?"},"type":"text","required":true},{"id":"bf2_3","text":{"en":"Describe the data labelling methodology and quality controls.","es":"Describe la metodología de etiquetado de datos y los controles de calidad."},"type":"text","required":true},{"id":"bf2_4","text":{"en":"Which types of bias have you identified in the source data?","es":"¿Qué tipos de sesgo has identificado en los datos de origen?"},"type":"multi_choice","required":true,"options":[{"value":"historical","label":{"en":"Historical bias","es":"Sesgo histórico"}},{"value":"representation","label":{"en":"Representation bias","es":"Sesgo de representación"}},{"value":"measurement","label":{"en":"Measurement bias","es":"Sesgo de medición"}},{"value":"aggregation","label":{"en":"Aggregation bias","es":"Sesgo de agregación"}},{"value":"evaluation","label":{"en":"Evaluation bias","es":"Sesgo de evaluación"}},{"value":"none","label":{"en":"None identified","es":"Ninguno identificado"}}],"allowNote":true,"help":{"meaning":{"en":"Use the standard taxonomy so the finding is precise: historical, representation, measurement, aggregation or evaluation bias.","es":"Usa la taxonomía estándar para que el hallazgo sea preciso: sesgo histórico, de representación, de medición, de agregación o de evaluación."},"example":{"en":"\"Representation bias: older applicants are under-represented in the data.\"","es":"«Sesgo de representación: los candidatos de mayor edad están infrarrepresentados en los datos.»"},"reference":{"en":"EU AI Act Art. 10","es":"Reglamento de IA de la UE, art. 10"}}}]},{"id":"bf3","title":{"en":"Fairness metrics","es":"Métricas de equidad"},"questions":[{"id":"bf3_1","text":{"en":"Which fairness metrics have been selected?","es":"¿Qué métricas de equidad se han seleccionado?"},"type":"multi_choice","required":true,"options":[{"value":"demographic_parity","label":{"en":"Demographic parity","es":"Paridad demográfica"}},{"value":"equalized_odds","label":{"en":"Equalized odds","es":"Igualdad de probabilidades"}},{"value":"predictive_parity","label":{"en":"Predictive parity","es":"Paridad predictiva"}},{"value":"calibration","label":{"en":"Calibration","es":"Calibración"}},{"value":"individual_fairness","label":{"en":"Individual fairness","es":"Equidad individual"}}],"allowNote":true,"help":{"meaning":{"en":"Fairness has several competing definitions; naming the metrics makes the trade-off explicit.","es":"La equidad tiene varias definiciones que compiten entre sí; nombrar las métricas hace explícito el equilibrio."},"example":{"en":"\"Equalized odds and calibration, because both error types matter here.\"","es":"«Igualdad de probabilidades y calibración, porque aquí importan ambos tipos de error.»"}}},{"id":"bf3_2","text":{"en":"Why are these metrics appropriate for the use case?","es":"¿Por qué son adecuadas estas métricas para este caso de uso?"},"type":"text","required":true},{"id":"bf3_3","text":{"en":"What is the disparate impact ratio across key groups?","es":"¿Cuál es el ratio de impacto desigual entre los grupos principales?"},"type":"text","required":true,"help":{"meaning":{"en":"The ratio of positive-outcome rates between a protected group and the reference group. Below 0.8 typically signals disparate impact.","es":"El cociente entre las tasas de resultado positivo de un grupo protegido y el grupo de referencia. Por debajo de 0,8 suele indicar impacto desigual."},"example":{"en":"\"0.72 for women vs men, below the 0.8 threshold.\"","es":"«0,72 para mujeres frente a hombres, por debajo del umbral de 0,8.»"}}},{"id":"bf3_4","text":{"en":"Are fairness metric thresholds meeting acceptable standards?","es":"¿Cumplen los umbrales de las métricas de equidad los estándares aceptables?"},"type":"single_choice","required":true,"options":[{"value":"all","label":{"en":"All metrics within acceptable range","es":"Todas las métricas dentro del rango aceptable"}},{"value":"most","label":{"en":"Most acceptable, minor gaps","es":"La mayoría aceptables, con brechas menores"}},{"value":"significant","label":{"en":"Significant gaps identified","es":"Se han identificado brechas significativas"}},{"value":"not_computed","label":{"en":"Metrics not yet computed","es":"Métricas aún no calculadas"}}],"allowNote":true}]},{"id":"bf4","title":{"en":"Bias testing results","es":"Resultados de las pruebas de sesgo"},"questions":[{"id":"bf4_1","text":{"en":"Describe the bias testing methodology used.","es":"Describe la metodología de pruebas de sesgo utilizada."},"type":"text","required":true},{"id":"bf4_2","text":{"en":"Report the disaggregated performance metrics across groups.","es":"Indica las métricas de rendimiento desagregadas por grupos."},"type":"text","required":true},{"id":"bf4_3","text":{"en":"What disparities were identified between groups?","es":"¿Qué disparidades se identificaron entre los grupos?"},"type":"text","required":true},{"id":"bf4_4","text":{"en":"Has intersectional analysis been performed?","es":"¿Se ha realizado un análisis interseccional?"},"type":"single_choice","required":true,"options":[{"value":"full","label":{"en":"Yes, full intersectional analysis","es":"Sí, análisis interseccional completo"}},{"value":"partial","label":{"en":"Partial intersectional analysis","es":"Análisis interseccional parcial"}},{"value":"planned","label":{"en":"Planned but not yet done","es":"Previsto pero aún no realizado"}},{"value":"none","label":{"en":"No","es":"No"}}],"allowNote":true,"help":{"meaning":{"en":"Intersectional analysis examines combinations of characteristics (e.g. race and gender together), where harm often concentrates.","es":"El análisis interseccional examina combinaciones de características (por ejemplo, raza y género juntas), donde suele concentrarse el perjuicio."},"example":{"en":"\"Full: tested race, gender and their combination.\"","es":"«Completo: se probaron raza, género y su combinación.»"}}}]},{"id":"bf5","title":{"en":"Mitigation measures","es":"Medidas de mitigación"},"questions":[{"id":"bf5_1","text":{"en":"Which pre-processing mitigations have been applied to the data?","es":"¿Qué mitigaciones de preprocesamiento se han aplicado a los datos?"},"type":"multi_choice","required":true,"options":[{"value":"resampling","label":{"en":"Resampling","es":"Remuestreo"}},{"value":"reweighting","label":{"en":"Reweighting","es":"Reponderación"}},{"value":"augmentation","label":{"en":"Data augmentation","es":"Aumento de datos"}},{"value":"proxy_removal","label":{"en":"Removal of proxy variables","es":"Eliminación de variables indirectas"}},{"value":"synthetic","label":{"en":"Synthetic data generation","es":"Generación de datos sintéticos"}},{"value":"none","label":{"en":"None","es":"Ninguna"}}],"allowNote":true},{"id":"bf5_2","text":{"en":"Which in-processing fairness techniques are used?","es":"¿Qué técnicas de equidad durante el procesamiento se utilizan?"},"type":"multi_choice","required":true,"options":[{"value":"adversarial_debiasing","label":{"en":"Adversarial debiasing","es":"Eliminación de sesgo adversaria"}},{"value":"regularisation","label":{"en":"Fairness-aware regularisation","es":"Regularización sensible a la equidad"}},{"value":"constrained_optimisation","label":{"en":"Constrained optimisation","es":"Optimización con restricciones"}},{"value":"none","label":{"en":"None","es":"Ninguna"}}],"allowNote":true},{"id":"bf5_3","text":{"en":"Which post-processing adjustments have been applied?","es":"¿Qué ajustes de posprocesamiento se han aplicado?"},"type":"multi_choice","required":true,"options":[{"value":"threshold_per_group","label":{"en":"Threshold adjustment per group","es":"Ajuste de umbral por grupo"}},{"value":"calibration","label":{"en":"Calibration","es":"Calibración"}},{"value":"reject_option","label":{"en":"Reject option classification","es":"Clasificación con opción de rechazo"}},{"value":"none","label":{"en":"None","es":"Ninguna"}}],"allowNote":true},{"id":"bf5_4","text":{"en":"Describe the ongoing monitoring plan for bias detection.","es":"Describe el plan de vigilancia continua para la detección de sesgos."},"type":"text","required":true}]},{"id":"bf6","title":{"en":"Assessment outcome","es":"Resultado de la evaluación"},"questions":[{"id":"bf6_1","text":{"en":"What is the overall fairness determination?","es":"¿Cuál es la determinación general de equidad?"},"type":"single_choice","required":true,"options":[{"value":"fair","label":{"en":"Fair — meets all fairness criteria","es":"Equitativo: cumple todos los criterios de equidad"}},{"value":"conditionally_fair","label":{"en":"Conditionally fair — acceptable with monitoring","es":"Equitativo con condiciones: aceptable con vigilancia"}},{"value":"unfair","label":{"en":"Unfair — significant bias requiring remediation","es":"No equitativo: sesgo significativo que exige corrección"}},{"value":"inconclusive","label":{"en":"Inconclusive — insufficient data","es":"No concluyente: datos insuficientes"}}],"allowNote":true},{"id":"bf6_2","text":{"en":"What residual bias risks remain after mitigation?","es":"¿Qué riesgos de sesgo residual quedan tras la mitigación?"},"type":"text","required":true},{"id":"bf6_3","text":{"en":"What specific actions are recommended to reduce bias further?","es":"¿Qué acciones concretas se recomiendan para reducir más el sesgo?"},"type":"text","required":true},{"id":"bf6_4","text":{"en":"When is the next re-assessment scheduled?","es":"¿Cuándo está prevista la próxima reevaluación?"},"type":"single_choice","required":true,"options":[{"value":"3m","label":{"en":"Within 3 months","es":"En un plazo de 3 meses"}},{"value":"6m","label":{"en":"Within 6 months","es":"En un plazo de 6 meses"}},{"value":"12m","label":{"en":"Within 12 months","es":"En un plazo de 12 meses"}},{"value":"material_change","label":{"en":"Upon material change only","es":"Solo ante un cambio sustancial"}}],"allowNote":true}]}]'::jsonb, 'EU AI Act Art. 10 / NIST AI RMF', true, 2, NULL, NOW(), NOW())
ON CONFLICT ("id") DO NOTHING;

-- 4. Retire the v1 SYSTEM templates for NEW assessments only. Guarded on
--    supersededAt IS NULL so a re-run never moves the date, and scoped to the
--    five known ids and isSystem so no org-authored template is touched.
UPDATE "ai_assessment_templates"
SET "version" = 1, "supersededAt" = NOW()
WHERE "id" IN ('system-fria-template', 'system-ai-risk-template', 'system-custom-template', 'system-conformity-template', 'system-bias-fairness-template')
  AND "isSystem" = true
  AND "supersededAt" IS NULL;
